      for(const candidate of Array.isArray(v.images)?v.images:[]){const parsed=image(candidate);if(parsed&&!seen.has(parsed.id)){images.push(parsed);seen.add(parsed.id);}if(images.length===MAX_IMAGES)break;}
      out[c.id]={text,images,completed:Boolean(v.completed&&(text.trim()||images.length))};
